import { get } from 'svelte/store';
import { api } from './api';
import { journal, todayKey } from './stores';
import type { DayEntry } from './types';

// Until this hour the evening review still belongs to the previous day, so a
// review written just after midnight lands on the day it describes.
const REVIEW_ROLLOVER_HOUR = 4;

/** YYYY-MM-DD for a local Date. */
export function dayKeyOf(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

/** The day the evening review is about: today, or yesterday shortly after midnight. */
export function reviewDayKey(): string {
  const d = new Date();
  if (d.getHours() < REVIEW_ROLLOVER_HOUR) d.setDate(d.getDate() - 1);
  return dayKeyOf(d);
}

export function emptyDay(id: string): DayEntry {
  const now = new Date().toISOString();
  return {
    id,
    items: [],
    planned_at: null,
    reviewed_at: null,
    focus: 0,
    productivity: 0,
    what_happened: '',
    prepare_tomorrow: '',
    created_at: now,
    updated_at: now,
  };
}

export function findDay(id: string): DayEntry | null {
  return get(journal).find((d) => d.id === id) ?? null;
}

/** The latest entry strictly before `id` — "yesterday" even across skipped days. */
export function previousDay(id: string): DayEntry | null {
  let best: DayEntry | null = null;
  for (const d of get(journal)) if (d.id < id && (!best || d.id > best.id)) best = d;
  return best;
}

/** Inserts or replaces the entry for its day and persists the journal. */
export async function saveDay(entry: DayEntry): Promise<void> {
  const stamped = { ...entry, updated_at: new Date().toISOString() };
  const next = [...get(journal).filter((d) => d.id !== stamped.id), stamped];
  journal.set(next);
  await api.saveJournal(next);
}

export { todayKey };

